{
  "items": [
    {
      "name": "Real.sqrt_eq_rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ (x : ℝ), √x = x ^ (1 / 2)"
    },
    {
      "name": "NNReal.sqrt_eq_rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ (x : NNReal), NNReal.sqrt x = x ^ (1 / 2)"
    },
    {
      "name": "CFC.sqrt_eq_rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.ContinuousFunctionalCalculus.Rpow.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : PartialOrder A] [inst_1 : Ring A] [inst_2 : StarRing A] [inst_3 : TopologicalSpace A]\n  [inst_4 : StarOrderedRing A] [inst_5 : Algebra ℝ A] [inst_6 : ContinuousFunctionalCalculus ℝ A IsSelfAdjoint]\n  [inst_7 : NonnegSpectrumClass ℝ A] [IsTopologicalRing A] [T2Space A] {a : A}, CFC.sqrt a = a ^ (1 / 2)"
    },
    {
      "name": "CFC.sqrt_rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.ContinuousFunctionalCalculus.Rpow.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : PartialOrder A] [inst_1 : Ring A] [inst_2 : StarRing A] [inst_3 : TopologicalSpace A]\n  [inst_4 : StarOrderedRing A] [inst_5 : Algebra ℝ A] [inst_6 : ContinuousFunctionalCalculus ℝ A IsSelfAdjoint]\n  [inst_7 : NonnegSpectrumClass ℝ A] [IsTopologicalRing A] [T2Space A] {a : A} {x : ℝ},\n  IsUnit a → x ≠ 0 → CFC.sqrt (a ^ x) = a ^ (x / 2)"
    },
    {
      "name": "Real.rpow_div_two_eq_sqrt",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x : ℝ} (r : ℝ), 0 ≤ x → x ^ (r / 2) = √x ^ r"
    }
  ]
}
